      "春天的阳光特别温暖，天地间的万物都苏醒过来了。天刚亮，树林里就传出了鸟儿的欢叫声。傍晚，青蛙都从冬眠中走了出来，在田野里叫个不停。昆虫们都纷纷地行动起来了。",
      "春来了，花园里的花开得更加娇艳。山上山下的桃花，千树万枝就像火焰一般地怒放了。小区里弯弯曲曲的小路旁，也开出了野花，小野菊也一丛丛由草堆里攒出头来，有白的、有红的、有黄的、还有紫的……它们都在竞相开放，争妍斗艳。",
      "春来了，青青的小草长得也很特别。在阳光下，草儿快乐地挺直了腰杆。分布在广州市区的绿地上，像一块块柔软的地毡，郊外绿油油的一大片，一眼望不到边。小区的墙角下也长出了小草，新生的绿草笑眯眯地站立在地上，像是在和低着头的蒲公英说着绵绵的情话。",
      "春来了，树木长得更加茂盛了，枝头上也吐出了细嫩的叶子。连一片黄叶都看不见了，风雨吹洗过的莽莽林海翠浪翻卷，千枝万叶洁净无尘。",
      "春来了，火车站里人山人海。他们提着旅行袋、背着行装，川流不息，原来是南来北往的打工族，他们一个个精神饱满，回到自己的工作岗位上。学生们都背着书包上学去了，他们穿上了色彩鲜艳的校服，一个个兴高采烈走进鲜花盛开的校园。",
