      "稻草人是农人亲手做的。他的骨架子是细竹枝,肌肉和皮肤是隔年的黄稻草。破竹篮子和残荷叶都可以做他的帽子;帽子下面的脸平板板的,分不清哪里是鼻子,哪里是眼睛。他的手没有手指,却拿着一把破扇子——其实也不能算拿,不过是用线拴住扇柄,挂在手上罢了。他的骨架子长得很,脚底下还有一段,农人把这一段插在田地中间的泥土里,他就整日整夜站在那里了。",
      "稻草人非常尽职尽责。要是拿牛跟他比,牛比他懒怠多了,牛有时躺在地上,抬起头看天。要是拿狗跟他比,狗比他顽皮多了,狗有时到处乱跑,累得主人四处去寻找。他从来不嫌烦,像牛那样躺着看天;也从来不贪玩儿,像狗那样到处乱跑。他安安静静地看着田地,手里的扇子轻轻摇动,赶走那些飞来吃稻穗的小雀。他不吃饭,也不睡觉,就是坐下歇一歇也不肯,总是直挺挺地站在那里。",
