      "秋天和春天一样,也有自己的工作日程表。不过,秋天的到来和春天的到来正好相反,秋天是从空中开始的。首先,树梢上的叶子最先变色,一点点变黄,变红,变褐。秋天,阳光没有那么充足了,叶子开始枯萎,不久就失去了碧绿的颜色。枝条上长着叶柄的地方,也开始衰落,有时,在无风的日子里,有些树木的叶子也会自动飘落下来。于是,一片片黄色的桦树叶、白杨树叶,都会一下子离开自己的枝条,纷纷扬扬地飘来飘去,最后悄无声息地落在了地面上。",
