      "我是午后在田野里闲逛时遇见那个小男孩的。他大约七八岁,拿一个玻璃瓶子在野地里来来回回地跑着。他单薄的衣衫被风吹得鼓鼓的,像是一张小帆。",
      "他在做什么呢?按照我的常识,农村的孩子常捉蚂蚱甚至蜻蜓装到瓶子里玩。见我看他,小男孩气喘吁吁地停下来,用小手捂住瓶口。",
