      "雨后的清晨,我在小区花坛边发现了几只蜗牛。它们背着浅棕色的“小房子”,壳上有螺旋状的花纹,一圈圈绕到顶端,特别有意思。蜗牛的身体软软的,爬行时会伸出两对触角——长触角顶端有小黑点,是它的眼睛;短触角用来感知周围的环境。",
