      "那是一株怎样的蒲公英!叶子的边缘已露出萎黄的老态,但叶子还是那样绿着,透着铁一般的色泽。叶们努力地贴向地面。霜一次又一次从天而降,蒲公英的茎慢慢垂下头来,用尽全部的力,贴向地面,贴向地面......他们明白,要想延续久远,就不能把头昂得太高,这样才能把最沉实的爱,尽可能多地传递给儿女。",
      "我的心不由得疼了一下,这像极了我的母亲。",
      "去年的这个时节,冬阳阻不住东奔西跑的北风,正如我阻不住我八十岁老母的脚。她在楼下,为我寻挖着蒲公英。“经霜的蒲公英能消炎败火,你这嗓子,应该吃点儿。”她半弓着腰,在衰草连片的枯黄里,神情专注地寻找那一小簇一小簇的绿。1她时不时地弓腰,用那曾经丰腴饱满而至今肉皮松弛的手,极其小心地翻捡着枯黄的草,似乎蒲公英长着脚,一不小心,受了惊吓,就会跑掉了似的。母亲的脚步,已失去了早年的利落,有些蹒跚。",
      "曾经,那是一双怎么样的脚啊!为了让孩子们正常地进出学校,她携夫带子,脚板直探向千里外陌生的异乡。",
      "后来,为了一家老小能吃上饭,她不分白天和夜晚,不惧炎阳和冰霜,用那细小的绣花针,绣出蟒袍上那呼之欲出的龙的模样,再用这双脚板,驱北风,走冰路,登火车,为一家换回不很丰裕的口粮。",
      "如今,母亲已去,留一棵蒲公英在这冬日里与我面对。2我伏下身,看着那泛黄的叶片,沿着叶脉轻抚,这碰到了我心里最柔软的角落。在我疼惜的泪光里,我又看到你透着如铁的刚强与坚毅,温暖着我层层叠叠的孤寂。",
