      "“你可真了不起!”他不禁对自己的勇敢大加赞赏,“全城的人都应该知道你的壮举。”说罢,小裁缝风风火火地为自己裁剪了一条腰带,缝好后,在上面绣了几个醒目的大字:“一下子打死七个”。他突然喊了起来:“我得让全世界的人都知道!”说到这儿,他激动得手舞足蹈。小裁缝把腰带系在腰间,打算出去闯世界。动身前,他四下里搜寻了一番,发现了一块陈干酪和灌木丛中绊住的一只小鸟,就随手装进口袋里。",
      "随后,他得意扬扬地上了路。由于个子矮小,他身轻如燕,走起来一点儿也不感到累。走着走着,他来到一座大山前。到了山顶,他发现一个力大无比的巨人正坐在那儿,悠然自得地环顾左右。小裁缝壮着胆子走到巨人跟前,跟他打招呼:“你好,伙计。你坐在这儿眺望大世界,是吧?我正要去闯闯,怎么样,想不想跟我一起去?”",
