      "孩提时,母亲常领我去峡谷深处,让我坐在一领蓑衣那么大的一块小小田塍上,自己浸没在齐膝的水田里插起秧来。这峡谷,背着阴,每天的日照不过3小时光景。这在村里,也是块十分贫瘠的谷地。我家就在这样的山谷口。谷里也有旱地,母亲种上了甘薯、萝卜之类。上那儿去,中间有条很深的小溪。上面架着桥,可每当发起大水,就常会被冲毁,母亲就常去修桥。",
      "因为这是母亲独自干活的峡谷,没法儿去托赖众乡邻。到时候,擅长修建寺庙和神社的木匠大伯,必定从哪儿归来,从山里砍来两根圆木,横在狭窄的小溪上,上面排好栗木板,堆上土。而后,叫我们兄弟踩结实,就成了一座坚固的红土桥了。",
      "约莫过一年,土桥旧了些,桥边杂草丛生,杂草下,一排排露出像在神社屋檐椽子上见到的那种白色缺口。而且,桥在变旧,栗木会腐烂,一看,桥的背面,竟长满了蘑菇。母亲把这些采了来,给我们做饭盒里的菜肴吃。",
